export const ALL_BUNDLES: UnifiedShopItem[] = FEATURED_BUNDLES.map((b, idx) => ({
  id: b.id,
  slug: b.id,
  name: b.name,
  category: 'bundle' as const,
  priceCents: b.priceCents,
  previewUrl: b.pieces[0]?.previewUrl || '',
  colors: ['purple', 'blue'] as ShopItemColor[],
  theme: idx % 2 === 0 ? ('Fantasy' as const) : ('Cute & Cozy' as const),
  rarity: b.rarity || 'legendary',
  isRecommended: b.isRecommended,
  bundle: b,
}));

/**
 * Returns complete combined catalog with server decoration overrides applied.
 */
export function getUnifiedCatalog(
  serverDecorations: AvatarDecorationDto[] = [],
): UnifiedShopItem[] {
  const serverMap = new Map<string, AvatarDecorationDto>();
  for (const s of serverDecorations) {
    serverMap.set(s.slug, s);
    serverMap.set(s.id, s);
  }

  const enrichedAvatars: UnifiedShopItem[] = ALL_AVATAR_DECORATIONS.map((item) => {
    const srv = serverMap.get(item.slug) || serverMap.get(item.id);
    if (srv) {
      return {
        ...item,
        id: srv.id,
        serverDecoration: srv,
        avatarDecoration: srv,
      };
    }
    return item;
  });

  const existingSlugs = new Set(enrichedAvatars.map((a) => a.slug));
  for (const srv of serverDecorations) {
    if (!existingSlugs.has(srv.slug)) {
      enrichedAvatars.push({
        id: srv.id,
        slug: srv.slug,
        name: srv.name,
        category: 'avatar',
        priceCents: srv.priceCents,
        previewUrl: srv.previewUrl,
        assetUrl: srv.assetUrl,
        colors: resolveItemColor(srv.slug, '', srv.name),
        theme: 'Fantasy',
        rarity: (srv.rarity as any) || 'epic',
        serverDecoration: srv,
        avatarDecoration: srv,
      });
    }
  }

  return [
    ...enrichedAvatars,
    ...ALL_PROFILE_FRAMES,
    ...ALL_NAMEPLATES,
    ...ALL_PROFILE_EFFECTS,
    ...ALL_BUNDLES,
  ].map((item) => ({
    ...item,
    name: normalizeShopItemName(item.name),
  }));
}

export function normalizeShopItemName(rawName: string): string {
  if (!rawName) return rawName;
  const name = rawName.trim();

  const OVERRIDES: Record<string, string> = {
    'Excalibur • Golden Ascension': 'Excalibur',
    'Elucidator • Midnight Break': 'Elucidator',
    'Blue Rose • Frost Shatter': 'Blue Rose',
    'Kirito • Jade Slash': 'Jade Slash',
    'Apex Circuit • Formula 1': 'Formula Apex',
    'Neon Paddock • Kart': 'Neon Kart',
    'Twin Blades • Frost & Gold': 'Frost Blades',
    'Twin Blades • Eclipse': 'Blade Eclipse',
    'Dragon Court • Jade': 'Jade Dragon',
    'Dragon Court • Sapphire': 'Sapphire Dragon',
    'Dragon Court • Gold': 'Gold Dragon',
    'Velvet Filigree • Ivory': 'Ivory Filigree',
    'Velvet Filigree • Crimson': 'Crimson Filigree',
    'Velvet Filigree • Amethyst': 'Amethyst Filigree',
    'Cloud Cat • Ivory': 'Ivory Cat',
    'Cloud Cat • Midnight': 'Midnight Cat',
    'Dragon • Obsidian Flame': 'Obsidian Flame',
    'Dragon • Obsidian': 'Obsidian Dragon',
    'Dragon • Gold': 'Gold Dragon',
    'Dragon • Sapphire': 'Sapphire Dragon',
    'Dragon • Silver': 'Silver Dragon',
    'Dragon • Crimson': 'Crimson Dragon',
    'Dragon • Emerald': 'Emerald Dragon',
    'Dragon • Amethyst': 'Amethyst Dragon',
    'Formula • Slipstream': 'Slipstream',
    'Kart • Neon Turbo': 'Neon Turbo',
    'Blade • Frost': 'Blade Frost',
    'Cat • Midnight': 'Midnight Cat',
    'Tiger · Bengal': 'Bengal Tiger',
    'Bear · Black': 'Black Bear',
    'Bear · Brown': 'Brown Bear',
    'Bear · Panda': 'Panda Bear',
    'Bear · Polar': 'Polar Bear',
    'Fairy · Amethyst': 'Amethyst Fairy',
    'Fallen Angel · Rose': 'Fallen Angel',
    'Fox · Red': 'Red Fox',
  };

  if (OVERRIDES[name]) {
    return OVERRIDES[name];
  }

  // Handle dot or bullet patterns
  if (name.includes('•') || name.includes('·')) {
    const parts = name
      .split(/[•·]+/)
      .map((p) => p.trim())
      .filter(Boolean);
    if (parts.length === 2) {
      const [category, modifier] = parts;
      if (category.toLowerCase() === 'cat ears') return `${modifier} Ears`;
      if (category.toLowerCase() === 'dragon') return `${modifier} Dragon`;
      if (category.toLowerCase() === 'bear') return `${modifier} Bear`;
      if (category.toLowerCase() === 'fox') return `${modifier} Fox`;
      if (category.toLowerCase() === 'tiger') return `${modifier} Tiger`;
      if (category.toLowerCase() === 'fairy') return `${modifier} Fairy`;
      return `${modifier} ${category}`.split(/\s+/).slice(0, 2).join(' ');
    } else if (parts.length >= 3) {
      const [cat, sub, mod] = parts;
      if (sub.includes('Maine Coon')) return 'Maine Coon';
      if (sub.includes('Dwarf')) return 'Dwarf Bunny';
      if (sub.includes('Lop')) return `${mod} Lop`.split(/\s+/).slice(0, 2).join(' ');
      return `${mod} ${sub}`.split(/\s+/).slice(0, 2).join(' ');
    }
  }

  // Remove bundle prefixes/suffixes
  const stripped = name.replace(/^\d+pc\s+/i, '').replace(/\s+Bundle.*$/i, '');
  const words = stripped.split(/\s+/);
  if (words.length > 2) {
    return words.slice(0, 2).join(' ');
  }
  return stripped;
}
